import '../../../../core/errors/app_exception.dart'; import '../../domain/entities/menu_item.dart'; import '../../domain/repositories/menu_repository.dart'; import '../datasources/menu_local_datasource.dart'; import '../datasources/menu_remote_datasource.dart';
class MenuRepositoryImpl implements MenuRepository { final MenuRemoteDataSource remote; final MenuLocalDataSource local; MenuRepositoryImpl({required this.remote,required this.local}); @override Future<List<MenuItemEntity>> getMenu({bool forceRefresh=false}) async { try{final r=await remote.getMenu();await local.saveMenu(r);return r;}catch(e){if(local.hasData)return local.getMenu();throw e is AppException?e:AppException(e.toString());} } }
